     /// — call it at launch and on dropdown open. The actor hop also keeps
     /// the work off the main actor.
     func refreshDetectedAgents() async {
         let next = await agentDetector.detectAll()
         detectedAgents = next
         // If the user previously picked a default that's no longer installed,
         // clear the pick so the behavior executor doesn't keep trying to spawn
         // a missing binary.
         if let pick = defaultAgent, next[pick] == nil {
             defaultAgent = nil
         }
         // First-detection auto-pick: when the user has never chosen a default
         // (or just cleared it because their previous pick disappeared), seed
         // it with the first installed agent from a fixed preference order.
         // We only do this when `defaultAgent == nil` so an explicit user pick
         // — including an explicit clear they re-trigger from the menubar —
         // never gets stomped on a later refresh.
         if defaultAgent == nil, !next.isEmpty {
             let preference: [AgentKind] = [.claudeCode, .agy, .codex, .opencode, .geminiCli]
             if let pick = preference.first(where: { next[$0] != nil }) {
                 defaultAgent = pick
             }
         }
     }

     /// Debounced search. Cancels any in-flight task and schedules a new one
     /// after 300ms. Clears results when the query is empty.
     func updateSearch(_ query: String) {
         searchQuery = query
         searchTask?.cancel()
         let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
         guard !trimmed.isEmpty else {
             searchResults = []
             isSearching = false
             return
         }
         guard let credentials, let slug = personalOrgSlug, !slug.isEmpty else { return }
         let client = WorkerClient(baseURL: credentials.baseURL, accessToken: credentials.accessToken)
         searchTask = Task { @MainActor [weak self] in
             try? await Task.sleep(for: .milliseconds(300))
             if Task.isCancelled { return }
             self?.isSearching = true
             do {
                 let response = try await client.searchKnowledge(orgSlug: slug, query: trimmed, limit: 5)
                 if Task.isCancelled { return }
                 self?.searchResults = response.items
             } catch {
                 Log.error(.sync, "search failed: \(error.localizedDescription)")
                 if !Task.isCancelled { self?.searchResults = [] }
             }
             self?.isSearching = false
         }
     }

