        entities: entityRows.map((e: any) => ({
          id: Number(e.id),
          name: e.name as string,
          entity_type: e.entity_type as string,
          metadata: (e.metadata ?? {}) as Record<string, unknown>,
        })),
        window: {
          id: result.window_id,
          run_id: watcherRunId,
          behavior_id: Number(result.behavior_id),
          window_start: result.window_start,
          window_end: result.window_end,
          granularity: timeGranularity,
          content_analyzed: batchContentIds.length,
        },
        behavior: {
          id: Number(result.behavior_id),
          slug: (watcherMeta[0]?.slug ?? `watcher-${result.behavior_id}`) as string,
          name: (watcherMeta[0]?.name ?? `watcher-${result.behavior_id}`) as string,
          version: Number(row.watcher_version ?? 1),
        },
        organization_id: orgId,
        organization_slug: String(row.organization_slug),
      };

      const MAX_ATTEMPTS = 3;
      for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
        const execResult = await executeReaction({
          compiledScript: row.reaction_script_compiled as string,
          context: reactionContext,
          env: env as Record<string, string | undefined>,
        });

        await trackWatcherReaction({
          organizationId: orgId,
          watcherId: Number(result.behavior_id),
          windowId: result.window_id,
          reactionType: 'script_execution',
          toolName: 'reaction_executor',
          toolArgs: { attempt },
          toolResult: { success: execResult.success, error: execResult.error },
        });

        if (execResult.success) {
          reactionStatus = 'success';
          logger.info(
            {
              watcher_id: result.behavior_id,
              window_id: result.window_id,
              attempt,
									asMergeProposal(proposal).winner_entity_id,
								]
							: [changedEntityId(proposal)],
				organizationId: ctx.organizationId,
				originId: `run_${runId}_pending`,
				title: `${actionLabel} — pending approval`,
				content:
					proposal.reason ??
					(operation === "update"
						? `${actorNoun} proposed updating ${fieldList} on this entity.`
						: operation === "delete"
							? `${actorNoun} proposed deleting this entity.`
							: operation === "merge"
								? `${actorNoun} proposed merging these entities.`
								: `${actorNoun} proposed creating this entity.`),
				semanticType: "operation",
				runId,
				interactionType: "approval",
				interactionStatus: "pending",
				interactionInput: proposal as unknown as Record<string, unknown>,
				metadata: {
					tool: actionKey,
					action_key: actionKey,
					action: operation === "update" ? "change" : operation,
					entity_id: "entity_id" in proposal ? proposal.entity_id : null,
					fields: updateProposal ? updateProposal.fields : null,
					current: mergeEventMetadata
						? mergeEventMetadata.current
						: updateProposal
							? (updateProposal.current ?? null)
							: deleteProposal
								? deleteProposal.current
								: null,
					proposal: createProposal
						? createProposal.proposal
						: mergeEventMetadata
							? mergeEventMetadata.proposal
							: deleteProposal
								? {
										entity_id: deleteProposal.entity_id,
										entity_type:
											entity?.entity_type ?? deleteProposal.current.entity_type,
										name: entity?.name ?? deleteProposal.current.name,
										force_delete_tree:
											deleteProposal.force_delete_tree ?? false,
									}
								: null,
					watcher_id: proposal.watcher_id ?? null,
					watcher_name: watcherName,
					watcher_agent_id: watcherAgentId,
					// The run window this proposal belongs to, if any. Stamped so the UI can
					// tell this proposal is part of a BATCH (the change-set card owns the
					// Approve/Reject decision) and suppress this card's own duplicate buttons.
					window_id: windowId ?? null,
					entity_name: entityName ?? null,
					entity_type: entityType ?? null,
					entity_slug: createProposal ? null : (entity?.slug ?? null),
					parent_slug: createProposal ? null : (entity?.parent_slug ?? null),
					parent_entity_type: createProposal
						? null
						: (entity?.parent_entity_type ?? null),
					attribution,
					initiator: {
						kind: initiatorColumns.initiatorKind,
						...initiatorColumns.initiatorRef,
					},
					reason: mergeEventMetadata
						? mergeEventMetadata.reason
						: (proposal.reason ?? null),
					proposer_rationale: mergeProposal?.proposer_rationale ?? null,
					status: "pending_approval",
		watcherId: rows[0].watcher_id != null ? Number(rows[0].watcher_id) : null,
		// entity_ids arrives as a raw PG array string under fetch_types:false — never
		// call .map on it directly. parsePgNumberArray handles both string and array.
		entityIds: parsePgNumberArray(rows[0].entity_ids),
	};
}

/**
 * Reject every pending proposal a watcher run produced, feeding the reason back
 * so the watcher's next run revises (the conversational revision loop — no inline
 * diff editor). Reuses the single-run reject path per proposal, then records the
 * reason as a `correction` feedback event keyed to the watcher — the SAME channel
 * getRecentFeedbackSummary injects into future watcher runs. That closes the loop
 * for real: the run view shows why the batch was rejected AND the watcher's next
 * turn reads "Past Corrections from User Feedback" and adjusts, rather than the
 * feedback sitting inert (sol review #10).
 */
async function handleRejectBatch(
	args: Static<typeof RejectBatchAction>,
	ctx: ToolContext,
): Promise<ManageOperationsResult> {
	const humanGate = requireHumanApprovalContext(ctx, "reject");
	if (humanGate) return humanGate;
	const resolved = await resolveBatchRunIds(args, ctx.organizationId);
	if (!Array.isArray(resolved)) return resolved;
	const runIds = resolved;
	if (batchRunSetChanged(runIds, args.run_ids)) {
		return {
			error: batchSetChangedError(args.window_id !== undefined, "rejecting"),
		};
	}
	await requireBatchApprovalAuthority("reject", runIds, ctx);
	const reason = args.reason ?? "Rejected by user";
	let rejected = 0;
	for (const runId of runIds) {
		const result = await handleReject(
			{ action: "reject", run_id: runId, reason },
			ctx,
		);
		if (!("error" in result)) rejected += 1;
	}
	// The `correction` feedback event is a WINDOW concept — it is keyed to the
	// watcher that produced the proposals so its next turn reads the rejection
	// and revises. A scope-targeted batch over queued connector operations has no
	// such producing run, so it records no correction; each rejected row still
	// supersedes its own card through the single-run reject path.
	if (rejected > 0 && args.window_id !== undefined) {
		const { watcherId, entityIds } = await resolveWindowRevisionContext(
			args.window_id,
			ctx.organizationId,
		);
		// A `correction` event — the durable, run-linked revision channel. Keyed to
		// the watcher (getRecentFeedbackSummary reads by watcher_id) and associated
		// with the entities the run touched, so both the watcher's next turn and the
		// entity/run views surface it. field_path='$batch_reject' marks it a
		// whole-run rejection (distinct from a single-field correction); the reason
		// rides `note`, which the summary renders verbatim.
		await insertEvent({
			entityIds,
			organizationId: ctx.organizationId,
			originId: `window_${args.window_id}_batch_reject`,
			title: `Batch rejected — ${rejected} proposals`,
			content: `The user rejected this run's proposals: ${reason}`,
			semanticType: "correction",
			createdBy: ctx.userId ?? null,
			metadata: {
				kind: "watcher_batch_reject",
				window_id: args.window_id,
				watcher_id: watcherId,
				field_path: "$batch_reject",
				mutation: "set",
				note: reason,
				rejected_count: rejected,
				reason,
			},
		});
	}
	return {
		action: "reject_batch",
		...(args.window_id !== undefined ? { window_id: args.window_id } : {}),
		rejected_count: rejected,
		run_ids: runIds,
		message:
			rejected === 0
				? args.window_id !== undefined
					? "No pending proposals for this run."
					: "No pending approvals matched this scope."
				: args.window_id !== undefined
				? `Rejected ${rejected} proposals. The Behavior's next run will see this feedback and revise.`
					: `Rejected ${rejected} queued operations.`,
	};
}
	if (ctx.agentId) {
		return {
			initiatorKind: "agent_session",
			initiatorRef: {
				agent_id: ctx.agentId,
				user_id: ctx.userId ?? null,
				client_id: ctx.clientId ?? null,
				conversation_id: ctx.sourceContext?.conversationId ?? null,
			},
			createdByUserId: ctx.userId ?? null,
		};
	}

	if (ctx.userId) {
		return {
			initiatorKind: "user",
			initiatorRef: { user_id: ctx.userId },
			createdByUserId: ctx.userId,
		};
	}

	return {
		initiatorKind: "system",
		initiatorRef: {},
		createdByUserId: null,
	};
}

/** Map persisted provenance to a run link, falling back if the route is incomplete. */
export function runPermalinkResource(
	initiator: {
		initiatorKind?: string | null;
		initiatorRef?: Record<string, unknown> | null;
	},
	runId: number,
	ownerAgentId: string | null | undefined,
): MemoryResource {
	if (initiator.initiatorKind !== "behavior" || !ownerAgentId) {
		return { kind: "run", runId };
	}
	// Reject the empty cases before coercing: Number(null) and Number("") are
	// both 0, a valid-looking id that would build a link to "Behavior 0".
	const rawBehaviorId = initiator.initiatorRef?.watcher_id;
	if (rawBehaviorId == null || rawBehaviorId === "") {
		return { kind: "run", runId };
	}
	const behaviorId = Number(rawBehaviorId);
	if (!Number.isSafeInteger(behaviorId) || behaviorId <= 0) {
		return { kind: "run", runId };
	}
	return {
		kind: "behavior_run",
		runId,
		agentId: ownerAgentId,
		behaviorId,
	};
}
